<script>
(async()=>{const form=document.getElementById('cateringForm'),message=document.getElementById('formMessage'),button=document.getElementById('submitButton');const show=(text,bad=false)=>{message.textContent=text;message.className='message '+(bad?'bad':'good')};try{const r=await fetch('api/public-brand.php',{headers:{Accept:'application/json'},cache:'no-store'}),d=await r.json();if(d.brand){const b=d.brand;document.documentElement.style.setProperty('--brand-primary',b.primary||'#d94a2b');document.documentElement.style.setProperty('--brand-secondary',b.secondary||'#ff835f');document.getElementById('brand').textContent=b.restaurantName||'Restaurant';const logo=document.getElementById('logo');if(b.logoUrl)logo.innerHTML=`<img src="${String(b.logoUrl).replaceAll('"','%22')}" alt="">`;else logo.textContent=b.logoText||'G';document.title=`Catering · ${b.restaurantName||'Restaurant'}`}}catch{}
form.addEventListener('submit',async event=>{event.preventDefault();message.className='message hidden';if(!form.reportValidity())return;button.disabled=true;button.textContent='Submitting…';const payload={csrf_token:document.getElementById('csrf').value,website_check:document.getElementById('website_check').value,contactName:document.getElementById('contactName').value.trim(),email:document.getElementById('email').value.trim(),phone:document.getElementById('phone').value.trim(),companyName:document.getElementById('companyName').value.trim(),eventName:document.getElementById('eventName').value.trim(),eventType:document.getElementById('eventType').value,eventDate:document.getElementById('eventDate').value,eventStartTime:document.getElementById('eventStartTime').value,eventEndTime:document.getElementById('eventEndTime').value,guestCount:document.getElementById('guestCount').value,venueName:document.getElementById('venueName').value.trim(),venueAddress:document.getElementById('venueAddress').value.trim(),serviceStyle:document.getElementById('serviceStyle').value,menuInterests:[...document.querySelectorAll('#menuChecks input:checked')].map(i=>i.value),beverageInterest:document.getElementById('beverageInterest').value,dietaryNeeds:document.getElementById('dietaryNeeds').value.trim(),staffingNeeds:document.getElementById('staffingNeeds').value.trim(),rentalNeeds:document.getElementById('rentalNeeds').value.trim(),setupNotes:document.getElementById('setupNotes').value.trim(),fulfillmentPreference:document.getElementById('fulfillmentPreference').value,budgetRange:document.getElementById('budgetRange').value,notes:document.getElementById('notes').value.trim(),consent:document.getElementById('consent').checked};try{const r=await fetch('api/public-catering.php',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-Token':payload.csrf_token},body:JSON.stringify(payload)}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'Could not submit the catering request.');show(d.message||'Catering request received.');form.reset();window.scrollTo({top:document.querySelector('.wrap').offsetTop-20,behavior:'smooth'});}catch(error){show(error.message||'Could not submit the catering request.',true)}finally{button.disabled=false;button.textContent='Submit catering request'}})})();
</script>
